public class Solution {
    public static double meanAbsoluteDeviation(double[] numbers) {
        double mean = calculateMean(numbers);
        return calculateMAD(mean, numbers);
    }

    private static double calculateMean(double[] numbers) {
        double sum = 0;
        for (double number : numbers) {
            sum += number;
        }
        return sum / numbers.length;
    }

    private static double calculateMAD(double mean, double[] numbers) {
        double sum = 0;
        for (double number : numbers) {
            sum += Math.abs(number - mean);
        }
        return sum / numbers.length;
    }
}

public class Solution {
    public static long[] intersperse(long[] numbers, long delimiter) {
        if (numbers.length == 0) {
            return new long[0];
        }

        long[] result = new long[numbers.length * 2 - 1];

        for (int i = 0; i < numbers.length - 1; i++) {
            result[i * 2] = numbers[i];
            result[i * 2 + 1] = delimiter;
        }

        result[result.length - 1] = numbers[numbers.length - 1];

        return result;
    }
}

