public class Solution {
    public static long[] sort_even(long[] a0) {
        int len = a0.length;
        long[] evens = new long[len / 2];
        long[] odds = new long[len / 2];
        for (int i = 0; i < len; i++) {
            if (i % 2 == 0) {
                evens[i / 2] = a0[i];
            } else {
                odds[i / 2] = a0[i];
            }
        }
        Arrays.sort(evens);
        Arrays.sort(odds);
        long[] ans = new long[len];
        int eIndex = 0, oIndex = 0;
        for (int i = 0; i < len; i++) {
            if (i % 2 == 0) {
                ans[i] = evens[eIndex++];
            } else {
                ans[i] = odds[oIndex++];
            }
        }
        if (eIndex > oIndex) {
            for (int i = eIndex; i < len; i++) {
                ans[i] = evens[i - eIndex];
            }
        }
        return ans;
    }
}

public class Solution {
