    private static String encode_cyclic(String s) {
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < ((s.length() + 2) / 3); i++) {
            int start = 3 * i;
            int end = Math.min(start + 3, s.length());
            String group = s.substring(start, end);
            if (group.length() == 3) {
                result.append(group.substring(1)).append(group.charAt(0));
            } else {
                result.append(group);
            }
        }
        return result.toString();
    }
}

