public class Solution {
    public static long fib4(long n) {
        long[] results = new long[4];
        results[0] = 0;
        results[1] = 0;
        results[2] = 2;
        results[3] = 0;

        if (n < 4) {
            return results[(int) n];
        }

        for (long i = 4; i <= n; i++) {
            long sum = results[(int) (i - 1)] + results[(int) (i - 2)] + results[(int) (i - 3)] + results[(int) (i - 4)];
