    private static long[] reverse(long[] array) {
        long[] reversed = array.clone();
        int left = 0;
        int right = array.length - 1;
        while (left < right) {
            long temp = reversed[left];
            reversed[left] = reversed[right];
            reversed[right] = temp;
            left++;
            right--;
        }
        return reversed;
    }
}

