import java.math.*;
public class Solution {
    public static long[] get_odd_collatz(long a0) {
        List<Long> oddCollatz = new ArrayList<>();
        if (a0 % 2 == 0) {
            oddCollatz = new ArrayList<>();
        } else {
            oddCollatz.add(a0);
        }
        while (a0 > 1) {
            if (a0 % 2 == 0) {
                a0 /= 2;
            } else {
                a0 = a0 * 3 + 1;
            }
            if (a0 % 2 == 1) {
                oddCollatz.add(a0);
            }
        }
        return oddCollatz.stream().mapToLong(Long::longValue).toArray();
    }
}

public class Solution {
    public static boolean valid_date(String date) {
        try {
            String[] parts = date.strip().split("-");
            int month = Integer.parseInt(parts[0]);
            int day = Integer.parseInt(parts[1]);
            int year = Integer.parseInt(parts[2]);

            if (month < 1 || month > 12) {
                return false;
            }
            if ((month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) && (day < 1 || day > 31)) {
                return false;
            }
            if ((month == 4 || month == 6 || month == 9 || month == 11) && (day < 1 || day > 30)) {
                return false;
            }
            if (month == 2 && (day < 1 || day > 29)) {
                return false;
            }
        } catch (Exception e) {
            return false;
        }

        return true;
    }
}

