public class Solution {
    public static String intersection(long[] a0, long[] a1) {
        boolean isPrime(int num) {
            if (num == 1 || num == 0)
                return false;
            if (num == 2)
                return true;
            for (int i = 2; i < num; i++)
                if (num % i == 0)
                    return false;
            return true;
        }

        long l = Math.max(a0[0], a1[0]);
        long r = Math.min(a0[1], a1[1]);
        long length = r - l;
        if (length > 0 && isPrime((int) length))
            return "YES";
        return "NO";
    }
}

import java.util.*;
import java.util.stream.*;
import java.util.function.*;
import java.math.*;
public class Solution {
    public static long[] minPath(long[][] grid, long k) {
        int n = grid.length;
        long val = (long) n * n + 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1L) {
                    List<Long> temp = new ArrayList<>();
                    if (i != 0) {
                        temp.add(grid[i - 1][j]);
                    }
                    if (j != 0) {
                        temp.add(grid[i][j - 1]);
                    }
                    if (i != n - 1) {
                        temp.add(grid[i + 1][j]);
                    }
                    if (j != n - 1) {
                        temp.add(grid[i][j + 1]);
                    }
                    val = Math.min(val, Collections.min(temp));
                }
            }
        }
        long[] ans = new long[(int) k];
        for (int i = 0; i < k; i++) {
            if ((i & 1) == 0) {
                ans[i] = 1L;
            } else {
                ans[i] = val;
            }
        }
        return ans;
    }
}

import java.util.*;
import java.util.stream.*;
import java.util.function.*;
import java.math.*;
public class Solution {
    public static double[] tri(long n) {
        if (n == 0) {
            return new double[]{1};
        }
        double[] myTri = new double[]{1, 3};
        for (int i = 2; i <= n; i++) {
            if (i % 2 == 0) {
                myTri = Arrays.copyOf(myTri, myTri.length + 1);
                myTri[myTri.length - 1] = (double) i / 2 + 1;
            } else {
                myTri = Arrays.copyOf(myTri, myTri.length + 1);
                myTri[myTri.length - 1] = myTri[i - 1] + myTri[i - 2] + ((double) i + 3) / 2;
            }
        }
        return myTri;
    }
}

public class Solution {
    public static long digits(long a0) {
        long product = 1;
        int oddCount = 0;
        String strA0 = Long.toString(a0);
        for (char c : strA0.toCharArray()) {
            int digit = Character.getNumericValue(c);
            if (digit % 2 == 1) {
                product *= digit;
                oddCount++;
            }
        }
        return oddCount == 0 ? 0 : product;
    }
}

