public class Solution {
    public static String fix_spaces(String text) {
        StringBuilder newText = new StringBuilder();
        int i = 0;
        int start = 0;
        int end = 0;
        while (i < text.length()) {
            if (text.charAt(i) == ' ') {
                end++;
            } else {
                if (end - start > 2) {
                    newText.append('-').append(text.charAt(i));
                } else if (end - start > 0) {
                    newText.append('_').append(newText.length() < 1 ? "" : "_").append(text.charAt(i));
                } else {
                    newText.append(text.charAt(i));
                }
                start = i + 1;
                end = i + 1;
            }
            i++;
        }
        if (end - start > 2) {
            newText.append('-');
        } else if (end - start > 0) {
            newText.append('_');
        }
        return newText.toString();
    }
}

