public class Solution {
    public static long[] order_by_points(long[] nums) {
        return Arrays.stream(nums)
                .mapToObj(Long::toString)
                .map(this::digitsSum)
                .sorted((a, b) -> a.compareTo(b))
                .map(String::toLong)
                .toArray();
    }

    private int digitsSum(String s) {
        long n = Long.parseLong(s);
        if (n < 0) {
            n = -1 * n;
            return -1;
        }
        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            chars[i] = Character.getChars(String.valueOf(n).charAt(i), 0)[0];
            n *= 10 + Character.getNumericValue(chars[i]);
        }
        return (int) Math.abs(n);
    }
}

