public class Solution {
    public static String[] bf(String planet1, String planet2) {
        String[] planetNames = {"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"};
        if (!contains(planetNames, planet1) || !contains(planetNames, planet2) || planet1.equals(planet2)) {
            return new String[0];
        }
        int planet1Index = getPosition(planetNames, planet1);
        int planet2Index = getPosition(planetNames, planet2);
        if (planet1Index < planet2Index) {
            return getPlanetsBetween(planetNames, planet1Index, planet2Index);
        } else {
            return getPlanetsBetween(planetNames, planet2Index, planet1Index);
        }
    }

    private static boolean contains(String[] array, String target) {
        for (String s : array) {
            if (s.equals(target)) {
                return true;
            }
        }
        return false;
    }

    private static int getPosition(String[] array, String target) {
        for (int i = 0; i < array.length; i++) {
            if (array[i].equals(target)) {
                return i;
            }
        }
        return -1;
    }

    private static String[] getPlanetsBetween(String[] planets, int start, int end) {
        String[] result = new String[end - start];
        for (int i = 0; i < result.length; i++) {
            result[i] = planets[start + i];
        }
        return result;
    }
}

