public class Solution {
    public static String Strongest_Extension(String class_name, String[] extensions) {
        String strong = extensions[0];
        int my_val = countUpperLetters(extensions[0]) - countLowerLetters(extensions[0]);
        for (String s : extensions) {
            int val = countUpperLetters(s) - countLowerLetters(s);
            if (val > my_val) {
                strong = s;
                my_val = val;
            }
        }

        return class_name + "." + strong;
    }

    private static int countUpperLetters(String str) {
        int count = 0;
        for (char c : str.toCharArray()) {
            if (Character.isUpperCase(c)) {
                count++;
            }
        }
        return count;
    }

    private static int countLowerLetters(String str) {
        int count = 0;
        for (char c : str.toCharArray()) {
            if (Character.isLowerCase(c)) {
                count++;
            }
        }
        return count;
    }
}

