import java.util.function.*;
import java.math.*;
public class Solution {
    public static String find_max(String[] words) {
        return Arrays.stream(words)
                .sorted((a, b) -> {
                    int lenDiff = Integer.compare(b.length(), a.length());
                    if (lenDiff == 0) {
                        Set<Character> setA = new HashSet<>();
                        Set<Character> setB = new HashSet<>();
                        for (char c : a.toCharArray()) {
                            setA.add(c);
                        }
                        for (char c : b.toCharArray()) {
                            setB.add(c);
                        }
                        return Integer.compare(setB.size(), setA.size());
                    } else {
                        return lenDiff;
                    }
                })
                .findFirst()
                .orElse("");
    }
}

public class Solution {
    public static long[] eat(long number, long need, long remaining) {
        long[] result = new long[2];
        if (need <= remaining) {
            result[0] = number + need;
            result[1] = remaining - need;
        } else {
            result[0] = number + remaining;
            result[1] = 0;
        }
        return result;
    }
}

