public class Solution {
    public static String solve(String s) {
        boolean flag = false;
        int index = 0;
        char[] newStr = s.toCharArray();
        for (char c : s.toCharArray()) {
            if (Character.isLetter(c)) {
                if (flag) {
                    newStr[index] = Character.toUpperCase(newStr[index]);
                } else {
                    newStr[index] = Character.toLowerCase(newStr[index]);
                }
                flag = !flag;
            }
            index++;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : newStr) {
            sb.append(c);
        }
        if (!flag) {
            return new StringBuilder(sb.toString()).reverse().toString();
        }
        return sb.toString();
    }
}

public class Solution {
    public static long[] generate_integers(long a0, long a1) {
        long lower = Math.max(2L, Math.min(a0, a1));
        long upper = Math.min(8L, Math.max(a0, a1));

        long[] result = new long[(upper - lower + 1)];
        for (long i = lower; i <= upper; i++) {
            if (i % 2 == 0) {
                result[i - lower] = i;
            }
        }

        return result;
    }
}
